<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Choose password · Fynefield CMS</title><link rel="stylesheet" href="<?= base_url('assets/css/admin.css') ?>"></head><body class="login-body"><form class="login-card" method="post" action="<?= site_url('admin/reset-password') ?>"><h1>Choose <span>password</span></h1><p>Use a new password with at least 12 characters. This link expires after one hour and can be used once.</p><?php if (session('error')): ?><div class="notice error"><?= esc(session('error')) ?></div><?php endif ?><?= csrf_field() ?><input type="hidden" name="token" value="<?= esc($token) ?>"><label>New password<input type="password" name="password" required autocomplete="new-password" minlength="12"></label><label>Confirm new password<input type="password" name="password_confirmation" required autocomplete="new-password" minlength="12"></label><button type="submit">Reset password</button><p><a href="<?= site_url('admin/login') ?>">Back to sign in</a></p></form></body></html>
